from lib import *
S = SS('n16')
steps = [
    step("Copy 的源码:新建一个 Context,复制 writermem(但 cp.writermem.ResponseWriter = nil,副本没有真正的写出对象)、Request、engine;index 设为 abortIndex、handlers 为 nil,所以副本上 Next 什么也不会执行;Keys 在 RLock 保护下用 maps.Clone 复制一份;Params 新分配切片再 copy,不与原来的共享底层数组;fullPath 原样带上。", t=tl(S(1)), mark=lidx(S(1), 'cp.writermem.ResponseWriter = nil', 'cp.index = abortIndex', 'cp.handlers = nil'), done=lidx(S(1), 'maps.Clone(cKeys)', 'copy(cp.Params, cParams)', 'cp.fullPath = c.fullPath'), kv=KV([['Keys', 'RLock 下 maps.Clone'], ['Params', '新切片 + copy'], ['ResponseWriter', '置 nil,副本不能写响应'], ['index / handlers', 'abortIndex / nil,Next 无效']], ['ResponseWriter'])),
    step("串行发 200 个请求,每个请求的 handler 起一个 goroutine,50 ms 后读 c.Param(\"id\") 并和进入时的 id 比较:GOMAXPROCS=10 时 196 个读到了别的请求的 id;GOMAXPROCS=4 时 196 个;GOMAXPROCS=1 时 199 个;改用 c.Copy() 三种情况下都是 0 个。Context 被 sync.Pool 复用,goroutine 读到的是后来某个请求留下的数据。", t=tl(S(2)), mark=lidx(S(2), 'GOMAXPROCS=10', 'GOMAXPROCS=4', 'GOMAXPROCS=1:不 Copy'), b=bars([['不 Copy,GOMAXPROCS=10', 196, '196 / 200 读错'], ['不 Copy,GOMAXPROCS=4', 196, '196 / 200'], ['不 Copy,GOMAXPROCS=1', 199, '199 / 200'], ['c.Copy()(三种设置)', 0, '0 / 200']], 200, mark=[0, 1, 2], done=[3]), kv=KV([['不 Copy', '约 98% 的 goroutine 读到别人的 id'], ['c.Copy()', '0 个'], ['原因', 'Context 在请求结束后放回 pool,下个请求 reset 后复用']], ['原因'])),
    step("同一个程序用 -race 编译,只发 20 个请求:Go 的竞态检测器报告了 10 处 WARNING: DATA RACE,退出码 66。第一份报告:goroutine 26 在 context.go:504 的 (*Context).Param() 读,goroutine 12 之前在 (*Context).reset() 里写(经过 Engine.ServeHTTP);报告涉及的 Gin 函数还有 Next 与 handleHTTPRequest。", t=tl(S(3)), mark=lidx(S(3), 'WARNING: DATA RACE', 'Read at', 'Previous write', 'gin.(*Context).reset()'), done=lidx(S(3), '检测到', '退出码 66', '(*Context).Param()'), kv=KV([['-race', '20 个请求就报 10 处 DATA RACE'], ['读', '(*Context).Param()(你的 goroutine)'], ['写', '(*Context).reset()(下一个请求的 ServeHTTP)']], ['-race'])),
    step("副本能做什么、不能做什么:Copy 之后原 Context 新加的 key(after)副本里没有;副本里有当时的 user=alice、Param=\"7\"、FullPath=\"/u/:id\";IsAborted=true,cp.Next() 什么也不执行;在副本上 cp.String(200, \"x\") 会 panic(nil pointer dereference,因为 ResponseWriter 是 nil);原请求仍正常返回 200 \"orig ok\"。", t=tl(S(4)), mark=lidx(S(4), 'panic=runtime error', 'IsAborted=true'), done=lidx(S(4), 'Copy 之后原 Context 新增的 key 在副本里吗: false', '原请求的响应'), kv=KV([['快照', 'Keys / Params / FullPath 是复制时的值'], ['不能写', 'cp.String 等会 nil panic'], ['Next', '无效']], ['不能写'])),
    step("Copy 不改变 Request 的生命周期:handler 返回之后,副本里的 cp.Request.Context().Err() 在 goroutine 一开始就是 context canceled,150 ms 后仍然是 context canceled。goroutine 里用副本的 Request.Context() 去调下游,请求结束后下游调用会立刻被取消。", t=tl(S(5)), mark=lidx(S(5), 'handler 刚返回时', '150ms 后'), kv=KV([['Request.Context()', 'handler 返回后被取消'], ['Copy', '不会延长它的生命'], ['要继续用', '在 goroutine 里另建 context(如 context.WithoutCancel)']], ['Request.Context()'])),
]
A = mkartn('n16', 16, 'Gin,Context,c.Copy,sync.Pool,并发,数据竞争,Go,真实验证,动画演示',
    '在 Gin v1.12.0 里实测 goroutine 里不 Copy 的后果:200 个串行请求里 196 个 goroutine 读到别的请求的 id;-race 报告 10 处 DATA RACE;c.Copy() 为 0;副本是快照,不能写响应,Request.Context() 在 handler 返回后仍被取消。',
    '在 handler 里起 goroutine 之后直接用 c,看起来能跑,其实读到的可能是别的请求的数据。这篇用 200 个串行请求量出出错的比例,用 -race 看竞态检测器的报告,再把 c.Copy() 能做和不能做的事逐项试一遍。',
    [('196 / 200', 'GOMAXPROCS=10 时,不 Copy 的 goroutine 读到别的请求 id 的个数(Copy 为 0)'), ('10 处', '-race 版本只发 20 个请求就报出的 DATA RACE'), ('context canceled', 'handler 返回后,副本里 Request.Context().Err() 的值')],
    [('Copy 做了什么', '<p>副本是一个全新的 Context:Keys 在读锁下克隆,Params 复制到新切片,Request、engine、fullPath 照搬;<code>handlers</code> 为 nil、<code>index</code> 为 abortIndex,所以 <code>Next</code> 什么都不会跑;<code>ResponseWriter</code> 被置为 nil,这是为了不让 goroutine 往已经结束的响应里写。</p>'),
     ('不 Copy 的后果', '<p>Context 在请求结束后被放回 <code>sync.Pool</code>,下一个请求 <code>reset</code> 之后复用。串行发 200 个请求,每个 goroutine 等 50 ms 再读 <code>c.Param("id")</code>,几乎全部(196~199 个)读到了别的请求的 id,不是偶然现象;改用 <code>c.Copy()</code> 则一个都没错。注意这不依赖多核:<code>GOMAXPROCS=1</code> 时错得更多。</p>'),
     ('竞态检测器怎么说', '<p>用 <code>-race</code> 编译同一份代码,20 个请求就能报出 10 处数据竞争:一边是你的 goroutine 在 <code>(*Context).Param()</code> 里读,另一边是后面的请求在 <code>(*Context).reset()</code> 里写。这类 bug 在压测前往往不显现,<code>-race</code> 的集成测试能提早发现。</p>'),
     ('副本的边界', '<p>副本是快照:复制之后原 Context 新增的 key 不会出现在副本里;可以读 Keys、Params、FullPath、Request;不能调用 <code>c.String</code> / <code>c.JSON</code> 等写响应的方法(nil 的 ResponseWriter 会 panic);<code>Next</code> 和 <code>Abort</code> 都没有意义。</p>'),
     ('请求取消', '<p>副本里的 <code>Request</code> 还是原来的那个,它的 <code>Context()</code> 在 handler 返回后立刻被取消。要在后台任务里继续调下游,需要另建一个脱离请求生命周期的 context(例如 <code>context.WithoutCancel(c.Request.Context())</code>,本文没有验证)。</p>')],
    steps,
    [ENV_N_GIN + '。第二、三节用真实的 httptest.NewServer 与 http.Client,串行发请求;-race 版本用 go build -race;GOMAXPROCS 通过环境变量设置;第四、五节同样用真实的本机 HTTP 服务;每种情形各一次(第二节每个设置 200 个请求)',
     '没有验证:并发请求(而不是串行)下的出错比例;context.WithoutCancel 在后台任务里的用法(只是推测的建议);Copy 的开销(分配与耗时);Gin 的 ContextWithFallback 打开时 Copy 的行为;其他版本的 Copy 实现'],
    'Context 复用与 Copy')
